function clearTiming(){if($('dp-pd-choice')){$('dp-pd-choice').innerHTML='<option value="">Calculate first</option>';$('dp-pd-choice').disabled=true;$('dp-rp-note').textContent=rpEnabled?'RP filter on · Calculate to find supporting PD choices.':'';}for(const [id,text] of [['dp-ad-windows','Calculate to list supporting PD periods within this AD.'],['dp-outer-transits','Calculate to find Jupiter/Saturn in event-significator stars and subs.'],['dp-sun-transits','Calculate to refine Sun, Moon or Lagna inside an eligible event-significator PD.']])$(id).textContent=text;}
