function supportingPD(data){const required=/^(?:1[0-2]|[1-9])(?:\s*,\s*(?:1[0-2]|[1-9]))*$/.test(data.rule.timingRaw||'')?data.rule.timingRaw.split(',').map(Number):[],hasUnparsedTiming=!!data.rule.timingRaw&&!required.length;const rows=KPHomeDasha.subdivide(selectedAD).map(p=>({...p,startMs:Math.max(p.startMs,selectedAD.startMs,selectedMD.startMs),endMs:Math.min(p.endMs,selectedAD.endMs,selectedMD.endMs)})).filter(p=>p.endMs>p.startMs).map(p=>{const all=uniq([...data.mdHouses,...data.adHouses,...houses(window.currentKPModel,p.lord)]);return {...p,pdHouses:houses(window.currentKPModel,p.lord),houses:all,matched:required.length?required.every(n=>all.includes(n)):proof(data.rule,all).matched,review:hasUnparsedTiming||!data.rule.automaticEligible};});data.pdCandidates=rows;return KPPDTransit.eligible(rows,KPPDTransit.significators(window.currentKPModel,data.rule),code);}
