async function refinePD(){if(!last?.calculated||busy)return;const data=last,pd=data.selectedPD,request=++token;data.refinement=[];data.sun=[];data.outer=KPPDTransit.clip(data.outerAll||[],pd,nativeOffset);$('dp-outer-transits').innerHTML=intervalHTML(data.outer);if(!pd){$('dp-sun-transits').textContent='No event-significator PD is available. No transit refinement was performed.';return;}const planet=val('dp-timing-planet')||'Su',rule=val('dp-timing-rule')||'sub',ids=KPPDTransit.significators(window.currentKPModel,data.rule),location=KPDefaultLocation.get();lockTiming(true);$('dp-sun-transits').textContent='Searching inside the selected event-significator PD…';try{const found=await KPPDTransit.refine({pd,offset:nativeOffset,id:code(pd.lord),planet,rule,significators:ids,signs:KPTransitEventChains.signs(code(pd.lord),currentKPModel),location,scan:options=>KPTransit.scan(options),cancelled:()=>token!==request,progress:p=>{if(token===request)$('dp-status').textContent='Refining '+(planet==='As'?'Lagna':planetName(planet))+' through PD '+code(pd.lord)+'… '+Math.round(p*100)+'%';}});if(token!==request)return;data.refinement=found;data.sun=planet==='Su'?found:[];data.timingPlanet=planet;data.timingRule=rule;$('dp-sun-transits').innerHTML='<p class="dp-sun-rule"><b>PD rule:</b> '+esc(code(pd.lord))+' is an event significator. '+esc(({sub:'Transit star is an event significator and sub lord is the selected PD.',star:'Transit nakshatra lord is the selected PD and sub lord is an event significator.',sign:'Transit is in a sign represented by the PD lord; star and sub are event significators.'})[rule])+' All entry/exit times are clipped to '+esc(local(pd.startMs))+' → '+esc(local(pd.endMs))+'.</p>'+intervalHTML(found);$('dp-status').textContent=data.pd.length+' eligible PD choices · selected '+code(pd.lord)+' · '+found.length+' '+(planet==='As'?'Lagna':planetName(planet))+' refinement windows.';}catch(e){if(token===request){$('dp-sun-transits').textContent=e.message;$('dp-status').textContent='PD refinement: '+e.message;}}finally{if(token===request){lockTiming(false);renderPDChoices(data);}}}
